import React from "react";

export function ButtonWithHoverAnimation() {
  return (
    <div>
    <button className="inline-block px-7 py-1.5 overflow-hidden text-sm font-semibold transition-transform rounded-full group text text-green-700/70 bg-green-300/30 hover500/70 hover">
      <span before="Send message" className="relative py-1.5 transition-transform inline-block before[attr(before)] before1.5 before before group-hover">Send message</span>
    </button>
    </div>
  );
}
